def _ref_is_prime(n):
    # Obviously-correct reference for integers: trial division.
    # Only defined for ints; non-ints are not prime.
    if isinstance(n, bool):
        return False
    if not isinstance(n, int):
        return False
    if n <= 1:
        return False
    if n <= 3:
        return True
    for p in range(2, int(math.isqrt(n)) + 1):
        if n % p == 0:
            return False
    return True

